#How far the mounted tool is through the limit it will reach first: PM, refurbishment, lifetime or refurbishment count.
#Re-read when its counts change (the cycle tags are in view.custom.tooling only to trigger this).
if not value['toolingAssetId']: return {'text': '', 'level': 0}
rows = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.tooling.getCounters({'toolingAssetId': value['toolingAssetId']}))
if not rows: return {'text': '', 'level': 0}
row = rows[0]
fmt = lambda v: system.kanoa.utilities.formatNumber('#,##0', v)
locale = self.session.props.locale
tr = lambda s: system.util.translate(s, locale)
unit = ' ' + tr({'runMinutes': 'min', 'calendarDays': 'days'}.get(row.get('lifeUnit'), 'cycles'))
worst = None
for name, pct, used, limit, units in (('PM', 'pmPct', 'pmUsed', 'pmInterval', unit),
									 ('Refurb', 'refurbPct', 'refurbUsed', 'refurbInterval', unit),
									 ('Life', 'lifetimePct', 'lifetimeUsed', 'lifetimeLimit', unit),
									 ('Refurbs', 'refurbCountPct', 'refurbCount', 'refurbLimit', '')):
	if row.get(pct) is None or not row.get(limit):
		continue
	if worst is None or row[pct] > worst[1]:
		worst = (name, row[pct], row.get(used) or 0, row[limit], units)
if worst is None:
	if row.get('lifetimeUsed') is None: return {'text': '', 'level': 0}
	return {'text': '%s %s%s' % (tr('Life'), fmt(row['lifetimeUsed']), unit), 'level': 0}
name, pct, used, limit, units = worst
return {'text': '%s %s/%s%s' % (tr(name), fmt(used), fmt(limit), units), 'level': row.get('level') or 0}

#The items counted, leaving out empty rows (a run's zero counts); the running item first, then the co-products
data = value['itemCounts']
#The running item's standard in its outfeed units per minute: the run's standard rate is in infeed units per its
#period, and each outfeed unit is packageCount infeed units
standard = None
if value['standardRate'] and value['packageCount'] and value['period'] in ('Minute', 'Hour'):
	standard = value['standardRate'] / value['packageCount'] / (60.0 if value['period'] == 'Hour' else 1.0)
units = value['outfeedUnits'] or ''
items = []
if hasattr(data, 'getRowCount'):
	for r in range(data.getRowCount()):
		outfeed = data.getValueAt(r, 'outfeed') or 0
		waste = data.getValueAt(r, 'waste') or 0
		if data.getValueAt(r, 'itemName') and (outfeed or waste):
			rate = data.getValueAt(r, 'outfeedRatePerMinute') if 'outfeedRatePerMinute' in data.getColumnNames() else None
			coProduct = bool(data.getValueAt(r, 'isCoProduct'))
			running = not coProduct and data.getValueAt(r, 'itemId') == value['itemId']
			items.append((coProduct, data.getValueAt(r, 'itemName'), outfeed, waste, rate, standard if running else None))
items.sort()

def rateText(rate, itemStandard):
	if itemStandard is None:
		return '' if rate is None else '{:,.1f} {} {}'.format(rate, units, system.util.translate('per min', self.session.props.locale))
	return '{} / {:,.1f} {} {}'.format('-' if rate is None else '{:,.1f}'.format(rate), itemStandard, units, system.util.translate('per min', self.session.props.locale))

coLabel = system.util.translate('{item} (co-product)', self.session.props.locale)
return [{'item': coLabel.replace('{item}', name) if coProduct else name,
		 'outfeed': '{:,.0f} {}'.format(outfeed, units),
		 'rate': rateText(rate, itemStandard),
		 #No waste shows nothing, not a red 0
		 'waste': '{:,.0f} {}'.format(waste, value['wasteUnits'] or '') if round(waste) else ''} for coProduct, name, outfeed, waste, rate, itemStandard in items]

# Operate: set the state, mount tools. Edit operations: set a speed-loss reason. Both can be limited to assets.
security = value['security']
userCRUD = security['userCRUD'] if security else {}
assetPath = value['assetPath'] or ''
def allowed(right):
	entry = userCRUD.get(right, {}) if userCRUD else {}
	if not entry.get('enabled'): return False
	assets = entry.get('assets') or []
	return not assets or any(assetPath == a or assetPath.startswith(a + '\\') for a in assets)
admin = bool(userCRUD) and userCRUD.get('isGatewayAdmin')
return {'canOperate': bool(admin or allowed('operateAssets')), 'canEditOperations': bool(admin or allowed('editOperations')), 'canConfigure': bool(admin or allowed('configureAssets'))}

#Who is logged in on this asset now: its open operator sessions. Read again each minute, and at once when a login or
#logout on this page sends operatorLoginUpdated (flxOperators). The runs while the view opens have no asset, and the
#runs can finish out of order, so use the asset now (as notificationSummary does, 868mvh89k)
assetId = value['assetId']
if not assetId:
	try: assetId = (self.custom.assetInfo or {}).get('assetId')
	except: assetId = None
if not assetId: return []
sessions = system.kanoa.operators.getOperators({'assetId': assetId, 'active': True})
names = []
for row in system.kanoa.utilities.convertDatasetToJSON(sessions):
	if row['userName'] and row['userName'] not in names: names.append(row['userName'])
return sorted(names, key=lambda name: name.lower())

#The asset's OEE/info tag: its kanoaMES OEE tags in one document that changes whenever any of them does, so the panel
#binds once instead of once per tag. Each folder as a dict, dates as dates and itemCounts as a dataset, as the
#individual tags gave them. None when the asset has no OEE tags
if value is None: return None
DATES = ['startDate', 'stateStart', 'shiftStart', 'shiftEnd', 'scheduleStart', 'scheduleEnd', 'lastUpdated']
ITEM_COLUMNS = ['itemId', 'itemName', 'isCoProduct', 'outfeed', 'waste', 'outfeedRatePerMinute']
def folder(name):
	try: values = value[name]
	except: return {}
	result = {}
	for key in values.keys():
		v = values[key]
		if key in DATES and v is not None: v = system.date.fromMillis(long(v))
		elif key == 'itemCounts': v = system.dataset.toDataSet(ITEM_COLUMNS, [[row[c] if c in row.keys() else None for c in ITEM_COLUMNS] for row in (v or [])])
		result[key] = v
	return result
return {'status': folder('Status'), 'run': folder('Current Run'), 'shift': folder('Current Shift')}

